// ** React Imports
import { Fragment, useEffect } from 'react'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import FormEditAgent from '../FormEditAgentComponent'
import { useDispatch } from 'react-redux'
import { editAgent, getDistributions, getUsers } from '../FormEditAgentComponent/store'
import { closeSwal, handleLoading, handleWarning, toastSuccess } from '../../sweetalert'
import { getData, reloadTable } from '../TableComponent/store'


const ModalEditAgent = (props) => {
  const {isShow, setIsShow, data} = props
  // const [isEditFunc, setIsEditFunc] = useState(false)
  const dispatch = useDispatch()
  
  useEffect(() => {
    dispatch(
      getUsers()
    )
    dispatch(
      getDistributions()
    )
  }, [])

  const handleEdit = () => {
    handleLoading('Vui lòng chờ hệ thống...')
    dispatch(editAgent())
    .then(res => {
      switch (res.payload) {
        case "success":
          dispatch(reloadTable({
            getData: (value) => dispatch(getData(value))
          }))
          .then(res => {
            console.log(res)
            closeSwal()
            toastSuccess("Chỉnh sửa thành công")
            setIsShow(false)
          })
          break
        case "error":
          handleWarning('Cảnh báo', 'Chỉnh sửa đại lý không thành công.<br/>Vui lòng kiểm tra lại!')
          break
        default:
          break
      }
    })
  }
  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-xl'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Chỉnh sửa thông tin đại lý</h1>
            <p>Bạn có thể chỉnh sửa thông tin đại lý tại đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col sm="12">
              <FormEditAgent data={data}/>
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              <Button className='me-1' color={'success'} onClick={() => handleEdit()}>
                Cập nhật
              </Button>
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModalEditAgent
