// ** React Imports
import { Fragment  } from 'react'

// ** Icons Imports
import { ArrowLeft, ArrowRight } from 'react-feather'
import { useDispatch, useSelector } from 'react-redux'

import { selectThemeColors } from '@utils'
import classNames from 'classnames'
// ** Reactstrap Imports
import { Label, Row, Col, Input, Form, Button, FormFeedback } from 'reactstrap'
import { setAddressAgent, setAllChoiceDistributions, setEmailAgent, setIdAgent, setNameAgent, setPhoneAgent } from '../store'
import Select, { components } from 'react-select' // eslint-disable-line

const vnf_regex = /((09|03|07|08|05)+([0-9]{8})\b)/
const email_regex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/
const AgentInfo = ({ stepper, type }) => {
  const store = useSelector(state => state.formEditAgent)
  console.log("form edit", store.allChoiceDistributions)
  const dispatch = useDispatch()

  const setIdAgentFunc = (e) => {
    dispatch(setIdAgent(e.target.value))
  }
  const setNameAgentFunc = (e) => {
    dispatch(setNameAgent(e.target.value))
  }
  const setAddressAgentFunc = (e) => {
    dispatch(setAddressAgent(e.target.value))
  }
  const setPhoneAgentFunc = (e) => {
    dispatch(setPhoneAgent(e.target.value))
  }
  const setEmailAgentFunc = (e) => {
    dispatch(setEmailAgent(e.target.value))
  }

  const distributions = store.allDistributions.map(item => ({value: item.id, label: `${item.name} - ${item.region} - ${item.city}`}))

  const handleChangeDistributions = (e) => {
    dispatch(
      setAllChoiceDistributions(e)
    )
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    console.log(e)

    let check = true
    if (store.idAgent !== '' && store.idAgent.length < 6) {
      check = false
    }

    if (store.nameAgent === null || store.nameAgent === '') {
      dispatch(
        setNameAgent('')
      )
      check = false
    }

    if (store.addressAgent === null || store.addressAgent === '') {
      dispatch(
        setAddressAgent('')
      )
      check = false
    }

    if (store.phoneAgent !== null && store.phoneAgent !== '' && !vnf_regex.test(store.phoneAgent)) {
      check = false
    }

    if (store.phoneAgent === null) {
      dispatch(
        setPhoneAgent('')
      )
      check = false
    }

    if (store.emailAgent !== null && store.emailAgent !== '' && !email_regex.test(store.emailAgent)) {
      check = false
    }

    if (store.emailAgent === '' || store.emailAgent === null) {
      dispatch(
        setEmailAgent('')
      )
      check = false
    }

    if (store.allChoiceDistributions !== null && store.allChoiceDistributions.length === 0) {
      check = false
    }

    if (store.allChoiceDistributions === null) {
      dispatch(
        setAllChoiceDistributions([])
      )
    }
    if (check) stepper.next()
  }

  // console.log("--", vnf_regex.test(store.phoneAgent))
  return (
    <Fragment>
      <div className='content-header'>
        <h5 className='mb-0'>THÔNG TIN CHUNG</h5>
        <small className='text-muted'>...</small>
      </div>
      <Form onSubmit={e => handleSubmit(e)}>
        <Row>
          <Col md='6' className='mb-1'>
            <Label className='form-label' for={`id-${type}`}>
              Mã đại lý (có thể để trống hoặc điền vào <b>6</b> ký tự)
            </Label>
            <Input disabled type='text' invalid={(store.idAgent !== '' && store.idAgent.length < 6)} name={`id-${type}`} id={`id-${type}`} value={store.idAgent} onChange={(e) => setIdAgentFunc(e)} placeholder="Mặc định tự động" maxLength={6}/>
            {((store.idAgent !== '' && store.idAgent.length < 6)) && <FormFeedback>Bạn phải điền đủ 6 ký tự hoặc đề trống</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label' for={`agent_name-${type}`}>
              Tên đại lý
            </Label>
            <Input 
              type='text' 
              invalid={store.nameAgent === ''} 
              name={`agent_name-${type}`} 
              id={`agent_name-${type}`} 
              value={store.nameAgent} 
              onChange={(e) => setNameAgentFunc(e)} />
            {(store.nameAgent === '') && <FormFeedback>Bạn chưa điền tên đại lý</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label' for={`agent_address-${type}`}>
              Địa chỉ đại lý
            </Label>
            <Input
              type='text'
              aria-label=''
              value={store.addressAgent}
              invalid={store.addressAgent === ''}
              onChange={(e) => setAddressAgentFunc(e)}
            />
            {(store.addressAgent === '') && <FormFeedback>Bạn chưa điền địa chỉ đại lý</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label' for={`agent_phone-${type}`}>
              Số điện thoại đại lý
            </Label>
            <Input
              id={`agent_phone-${type}`}
              type='number'
              aria-label=''
              invalid={store.phoneAgent !== null && !vnf_regex.test(store.phoneAgent)}
              value={store.phoneAgent}
              onChange={(e) => setPhoneAgentFunc(e)}
            />
            {(store.phoneAgent !== null && store.phoneAgent !== '' && !vnf_regex.test(store.phoneAgent)) && <FormFeedback>Số điện thoại đại lý chưa hợp lệ</FormFeedback>}
            {(store.phoneAgent === '') && <FormFeedback>Bạn chưa điền số điện thoại đại lý</FormFeedback>}
          </Col>
        </Row>
        <Row>
          <Col md='6' className='mb-1'>
              <Label className='form-label' for={`agent_address-${type}`}>
                Email đại lý
              </Label>
              <Input
                type='email'
                aria-label=''
                invalid={store.emailAgent !== null && !email_regex.test(store.emailAgent)}
                value={store.emailAgent}
                onChange={(e) => setEmailAgentFunc(e)}
              />
              {(store.emailAgent !== null && store.emailAgent !== '' && !email_regex.test(store.emailAgent)) && <FormFeedback>Email đại lý chưa hợp lệ</FormFeedback>}
              {(store.emailAgent === '') && <FormFeedback>Bạn chưa điền Email đại lý</FormFeedback>}
          </Col>  
          <Col md='6' className='mb-1'>
            <Label className='form-label'>Chọn kênh phân phối</Label>
            <Select
              isClearable={false}
              theme={selectThemeColors}
              defaultValue={
                store.allChoiceDistributions !== null ? [...store.allChoiceDistributions] : []
              }
              placeholder={"Chọn kênh phân phối"}
              isMulti
              name='colors'
              options={distributions}
              // className='react-select'
              classNamePrefix='select'
              onChange={(e) => handleChangeDistributions(e)}
              className={classNames('react-select', { 'is-invalid': store.allChoiceDistributions !== null && store.allChoiceDistributions.length === 0})}
            />
            {(store.allChoiceDistributions !== null && store.allChoiceDistributions.length === 0) && <FormFeedback>Bạn chưa chọn kênh phân phối cho đại lý</FormFeedback>}
          </Col>  
        </Row>
        <div className='d-flex justify-content-between'>
          <Button color='secondary' className='btn-prev' outline disabled>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' type='submit' className='btn-next'>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
        </div>
      </Form>
    </Fragment>
  )
}

export default AgentInfo
