// ** React Imports
import { Fragment, useEffect } from 'react'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import FormAddAgent from '../FormAddAgentComponent'
import { useDispatch } from 'react-redux'
import { getDistributions, getUsers } from '../FormAddAgentComponent/store'
import SelectOwnerReactCST from '../SelectComponent'

const ModaAddAgent = (props) => {
  const {isShow, setIsShow} = props
  const dispatch = useDispatch()
  useEffect(() => {
    console.log()
    dispatch(
      getUsers()
    )
    
    dispatch(
      getDistributions()
    )
  }, [])

  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-xl'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Thêm đại lý mới</h1>
            <p>Bạn có thể thêm một đại lý mới ở đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col sm="12">
              <FormAddAgent showModalParent={(value) => setIsShow(value)}/>
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModaAddAgent
