/* eslint-disable no-useless-return */
/* eslint-disable comma-dangle */
/* eslint-disable semi */
/* eslint-disable no-unused-vars */
// ** React Imports
import { useState, Fragment, useEffect } from "react";
import Select from "react-select";
// import classNames from 'classnames'

// ** Icons Imports
import { ArrowLeft, ArrowRight, Save } from "react-feather";
import { useDispatch, useSelector } from "react-redux";
import * as yup from 'yup'
// ** Utils
// import { selectThemeColors } from '@utils'
// import { useDispatch, useSelector } from 'react-redux'

// ** Reactstrap Imports
import { Label, Row, Col, Input, Form, Button, FormFeedback } from "reactstrap";
import {
  closeSwal,
  handleLoading,
  handleWarning,
  toastSuccess,
} from "../../../sweetalert";
import SelectOwnerReactCST from "../../SelectComponent";
import { getData, reloadTable } from "../../TableComponent/store";
import {
  addAgentWithOwner,
  resetStore,
  setAddressOwner,
  setConfirmPasswordOwner,
  setEmailOwner,
  setIdOwner,
  setNameOwner,
  setPasswordOwner,
  setPhoneOwner,
} from "../store";

const vnf_regex = /((09|03|07|08|05)+([0-9]{8})\b)/
const email_regex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/

const NewAccountDetails = ({ stepper, showModalParent }) => {
  const dispatch = useDispatch();

  const store = useSelector((state) => state.formAddAgent);

  const addAgentFunc = (e) => {
    e.preventDefault()
    // if (store.idOwner === null) {
    //   dispatch(setIdOwner(""));
    //   return;
    // }
    let check = true;

    if (store.nameOwner === null || store.nameOwner === '') {
      dispatch(setNameOwner(''))
      check = false;
    }
    if (store.phoneOwner === null || store.phoneOwner === '') {
      dispatch(setPhoneOwner(''))
      check = false;
    }
    if (store.addressOwner === null || store.addressOwner === '') {
      dispatch(setAddressOwner(''))
      check = false;
    }
    if (store.emailOwner === null || !email_regex.test(store.emailOwner)) {
      dispatch(setEmailOwner(''))
      check = false;
    }
    if (store.passwordOwner === null || store.passwordOwner.length < 8) {
      check = false;
      if (store.passwordOwner === null) {
        dispatch(setPasswordOwner(''))
      }
    }
    if (store.confirmPasswordOwner === null ||
      store.confirmPasswordOwner !== store.passwordOwner) {
        if (store.confirmPasswordOwner === null) {
          dispatch(setConfirmPasswordOwner(''))
        }
      check = false;
    }
    if (!check) return;
    handleLoading("Đang thêm đại lý mới...");
    dispatch(addAgentWithOwner()).then((res) => {
      switch (res.payload) {
        case "success":
          dispatch(
            reloadTable({
              getData: (value) => dispatch(getData(value)),
            })
          ).then((res) => {
            // console.log(res);
            closeSwal();
            toastSuccess("Thêm thành công");
            showModalParent(false);
            dispatch(resetStore(""));
          });
          break;
        case "error":
          handleWarning(
            "Cảnh báo",
            "Thêm đại lý mới không thành công.<br/>Vui lòng kiểm tra lại!"
          );
          break;
        default:
          break;
      }
    });
  };

  const setNameOwnerFunc = (e) => {
    dispatch(setNameOwner(e.target.value));
  };
  const setEmailOwnerFunc = (e) => {
    dispatch(setEmailOwner(e.target.value));
  };
  const setPasswordOwnerFunc = (e) => {
    dispatch(setPasswordOwner(e.target.value));
  };
  const setConfirmPasswordOwnerFunc = (e) => {
    dispatch(setConfirmPasswordOwner(e.target.value));
  };
  const setPhoneOwnerFunc = (e) => {
    dispatch(setPhoneOwner(e.target.value));
  };
  const setAddressOwnerFunc = (e) => {
    dispatch(setAddressOwner(e.target.value));
  };

  // const [options, setOptions] = useState([])

  // useEffect(() => {
  //   setOptions(store.allOwners.map(item => ({value: item.id, label: `⫸ ${item.name} ⥈ ${item.email}`})))
  // }, [store])

  // const setIdOwnerFunc = (value) => {
  //   console.log(value)
  //   dispatch(
  //     setIdOwner(value)
  //   )
  // }
  return (
    <Fragment>
      <div className="content-header">
        <h5 className="mb-0">Thông tin chủ đại lý</h5>
        <small className="text-muted">Hiển thị thông tin chủ đại lý</small>
      </div>
      <Form onSubmit={addAgentFunc}>
        <Row>
          <Col md="6" className="mb-1">
            <Label className="form-label" for="name-owner">
              Tên chủ đại lý
            </Label>
            <Input
              type="text"
              aria-label=""
              invalid={store.nameOwner === ""}
              value={store.nameOwner || ""}
              onChange={setNameOwnerFunc}
              id={`name-owner`}
              name={`name-owner`}
            />
            {store.nameOwner === "" && (
              <FormFeedback>Bạn chưa điền tên chủ đại lý</FormFeedback>
            )}
          </Col>
          <Col md="6" className="mb-1">
            <Label className="form-label" for="phone-owner">
              Số điện thoại chủ đại lý
            </Label>
            <Input
              type="number"
              invalid={
                store.phoneOwner !== null && !vnf_regex.test(store.phoneOwner)
              }
              aria-label=""
              value={store.phoneOwner || ""}
              onChange={setPhoneOwnerFunc}
              id={`phone-owner`}
              name={`phone-owner`}
            />
            {store.phoneOwner !== "" && !vnf_regex.test(store.phoneOwner) && (
              <FormFeedback>Số điện thoại không hợp lệ</FormFeedback>
            )}
            {store.phoneOwner === "" && (
              <FormFeedback>Bạn chưa điền số điện thoại</FormFeedback>
            )}
          </Col>
          <Col md="6" className="mb-1">
            <Label className="form-label" for="address-owner">
              Địa chỉ chủ đại lý
            </Label>
            <Input
              type="text"
              aria-label=""
              invalid={store.addressOwner === ""}
              value={store.addressOwner || ""}
              onChange={setAddressOwnerFunc}
              id={`address-owner`}
              name={`address-owner`}
            />
            {store.addressOwner === "" && (
              <FormFeedback>Bạn chưa điền địa chỉ chủ đại lý</FormFeedback>
            )}
          </Col>
          <Col md="6" className="mb-1">
            <Label className="form-label" for={`em-ail-owner`}>
              Email chủ đại lý
            </Label>
            <Input
              type="email"
              aria-label=""
              invalid={
                store.emailOwner === null ? false : !email_regex.test(store.emailOwner)
              }
              value={store.emailOwner || ""}
              onChange={setEmailOwnerFunc}
              id="em-ail-owner"
              name="em-ail-owner"
            />
            {store.emailOwner !== "" &&
              !email_regex.test(store.emailOwner) && (
                <FormFeedback>Email không hợp lệ</FormFeedback>
              )}
            {store.emailOwner === "" && (
              <FormFeedback>Bạn chưa điền email</FormFeedback>
            )}
          </Col>
        </Row>
        <Row>
          <Col md="6" className="mb-1">
            <Label className="form-label" for={`password-owner`}>
              Mật khẩu
            </Label>
            <Input
              type="text"
              style={{
                "text-security": "disc",
                "-moz-text-security": "disc",
                "-webkit-text-security": "disc",
              }}
              aria-label=""
              value={store.passwordOwner || ""}
              invalid={
                store.passwordOwner === null ? false : store.passwordOwner?.length < 8
              }
              id="password-owner"
              name="password-owner"
              onChange={setPasswordOwnerFunc}
            />
            {store.passwordOwner === "" && (
              <FormFeedback>Bạn chưa điền mật khẩu</FormFeedback>
            )}
            {store.passwordOwner !== "" && store.passwordOwner?.length < 8 && (
              <FormFeedback>Mật khẩu phải có ít nhất 8 ký tự</FormFeedback>
            )}
          </Col>
          <Col md="6" className="mb-1">
            <Label className="form-label" for={`confirm-password-owner`}>
              Xác nhận mật khẩu
            </Label>
            <Input
              type="text"
              style={{
                "text-security": "disc",
                "-moz-text-security": "disc",
                "-webkit-text-security": "disc",
              }}
              aria-label=""
              invalid={
                store.confirmPasswordOwner !== null &&
                store.confirmPasswordOwner !== store.passwordOwner
              }
              value={store.confirmPasswordOwner || ""}
              onChange={setConfirmPasswordOwnerFunc}
              id={`confirm-password-owner`}
              name={`confirm-password-owner`}
            />
            {store.confirmPasswordOwner === "" && (
              <FormFeedback>Bạn chưa xác nhận mật khẩu</FormFeedback>
            )}
            {store.confirmPasswordOwner !== "" &&
              store.confirmPasswordOwner !== store.passwordOwner && (
                <FormFeedback>Mật khẩu xác nhận không chính xác</FormFeedback>
              )}
          </Col>
        </Row>
        {/* <Select 
          isClearable={false}
          theme={selectThemeColors}
          defaultValue={[]}
          placeholder={"Chọn chủ đại lý"}
          isMulti={false}
          name='colors'
          options={options}
          // className='react-select'
          classNamePrefix='select'
          onChange={(value) => setIdOwnerFunc(value)}
          className={classNames('react-select', { 'is-invalid': store.idOwner === ''})}
        /> */}
        {store.idOwner === "" && (
          <FormFeedback>Bạn chưa chọn chủ đại lý</FormFeedback>
        )}
        {/* <SelectOwnerReactCST options={options} onChange={(value) => setIdOwnerFunc(value)}/> */}
        {/* </Form> */}
        <div className="d-flex justify-content-between mt-1">
          <Button
            color="secondary"
            type="button"
            className="btn-prev"
            outline
            onClick={() => stepper.previous()}
          >
            <ArrowLeft
              size={14}
              className="align-middle me-sm-25 me-0"
            ></ArrowLeft>
            <span className="align-middle d-sm-inline-block d-none">Trước</span>
          </Button>
          <Button color="success" className="btn-next" type="submit">
            <Save size={16} className="align-middle ms-sm-25 ms-0 me-1"></Save>
            <span className="align-middle d-sm-inline-block d-none">
              Lưu đại lý
            </span>
          </Button>
        </div>
      </Form>
    </Fragment>
  );
};

export default NewAccountDetails;
