// ** React Imports
import { useRef, useState, useMemo } from 'react'

// ** Custom Components
import Wizard from '@components/wizard'

// ** Steps
import Address from './steps/Address'
import SocialLinks from './steps/SocialLinks'
import PersonalInfo from './steps/PersonalInfo'
import AccountDetails from './steps/AccountDetails'
import AgentInfo from './steps/AgentInfo'
import { useDispatch, useSelector } from 'react-redux'
import { getUserEdit, initStore } from './store'
import NewAccountDetails from './steps/NewAccountDetails'

const FormEditAgent = ({showModalParent, data}) => {
  const ref = useRef(null)
  const dispatch = useDispatch()
  const store = useSelector(state => state.formEditAgent)

  useMemo(() => {
    const tmp = store.allOwners.filter(item => item.id === data.user_id)
    dispatch(
      initStore(
        {
          id: data.id,
          idAgent: data.agency_id,
          nameAgent: data.name,
          addressAgent: data.address,
          phoneAgent: data.phone,
          emailAgent: data.email,
          
          idOwner: (tmp.length > 0) ? {value: tmp[0].id, label: `⫸ ${tmp[0].name} ⥈ ${tmp[0].email}`} : {value: data.user_id, label: `⫸ Không tìm thấy`},
          allChoiceDistributions: data.distributor_channel.map(item => {
            const distributions = store.allDistributions.filter(item2 => item2.id === item.distributor_channel_id)
            if (distributions.length > 0) {
              return ({value: item.distributor_channel_id, label: `${distributions[0].name} - ${distributions[0].region} - ${distributions[0].city}`})
            } else {
              return ({value: item.distributor_channel_id, label: `Không tìm thấy`})
            }
          })
        }
      )
    )
    dispatch(
      getUserEdit(data.user_id)
    )
  }, [])
  // ** State
  const [stepper, setStepper] = useState(null)

  const steps = [
    {
      id: 'agent-info',
      title: 'Thông tin chung',
      subtitle: 'Hiển thị thông tin đại lý',
      content: <AgentInfo stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'detail-info',
      title: 'Thông tin tài khoản',
      subtitle: 'Hiển thị thông tin tài khoản.',
      content: <NewAccountDetails stepper={stepper} showModalParent={(value) => showModalParent(value)} type='wizard-vertical' />
    }
  ]

  return (
    <div className='vertical-wizard'>
      <Wizard
        type='modern-vertical'
        ref={ref}
        steps={steps}
        options={{
          linear: true
        }}
        instance={el => setStepper(el)}
      />
    </div>
  )
}

export default FormEditAgent
