// ** Custom Components
import Avatar from '@components/avatar'

// ** Third Party Components
import axios from 'axios'
import { Fragment, useState } from 'react'
import { MoreVertical, Edit, FileText, Archive, Trash, Eye, Delete } from 'react-feather'
import { useDispatch, useSelector } from 'react-redux'

// ** Reactstrap Imports
import { Badge, DropdownToggle, DropdownMenu, DropdownItem, Row, Col, Button, UncontrolledTooltip } from 'reactstrap'
import { closeSwal, handleQuestion, toastSuccess } from '../../sweetalert'
import ModalEditAgent from '../ModalEditAgentComponent'
import { deleteAgency, getData, reloadTable } from './store'


export let data

// ** Get initial Data
axios.get('/api/datatables/initial-data').then(response => {
  data = response.data
})

// ** Expandable table component
const ExpandableTable = ({ data }) => {
  return (
    <div className='expandable-content p-2'>
      <p>
        <span className='fw-bold'>City:</span> {data.city}
      </p>
      <p>
        <span className='fw-bold'>Experience:</span> {data.experience}
      </p>
      <p className='m-0'>
        <span className='fw-bold'>Post:</span> {data.post}
      </p>
    </div>
  )
}

// ** Table Server Side Column
export const serverSideColumns = [
  {
    sortable: true,
    name: 'Mã đại lý',
    maxWidth: '150px',
    selector: row => row.agency_id
  },
  {
    sortable: true,
    name: 'Tên đại lý',
    minWidth: '180px',
    selector: row => row.name
  },
  {
    sortable: true,
    name: 'Chủ đại lý',
    minWidth: '180px',
    selector: row => row.user_name
  },
  {
    sortable: true,
    name: 'Địa chỉ',
    minWidth: '200px',
    selector: row => row.address
  },
  {
    sortable: true,
    name: 'Số điện thoại',
    minWidth: '200px',
    selector: row => row.phone
  },
  {
    sortable: true,
    name: 'Email đại lý',
    minWidth: '200px',
    selector: row => row.email
  },
  {
    sortable: true,
    name: 'Chủ đại lý',
    minWidth: '300px',
    selector: row => {
      const store = useSelector(state => state.formEditAgent)
      const tmp = store.allOwners.filter(item => item.id === row.user_id)
      return (
        (tmp.length > 0) ? (`⫸ ${tmp[0].name} ⥈ ${tmp[0].email}`) : ('⫸ Không tìm thấy')
      )
    }
  },
  {
    name: 'Hành động',
    minWidth: '150px',
    selector: (row) => {
      console.log(row)
      const [isShowModalAgent, setIsShowModalAgent] = useState(false)
      const dispatch = useDispatch()
      const handleDeleteAgency = (id) => {
        handleQuestion('Bạn muốn tiếp tục?', 'Việc xóa đi một đại lý sẽ không thể hoàn tác lại.', (isConfirmed) => {
          if (isConfirmed) {
            dispatch(deleteAgency({
              id
            }))
            .then(() => {
              dispatch(reloadTable({
                getData: (value) => dispatch(getData(value))
              }))
              .then(res => {
                console.log(res)
                closeSwal()
                toastSuccess("Xóa thành công")
              })
            })
          }
        })
      }
      return (
        <Fragment>
          <ModalEditAgent isShow={isShowModalAgent} setIsShow={setIsShowModalAgent} data={row}/>
          <div className='d-flex '>
              {/* <div>
                <Button.Ripple className='btn-icon' color='flat-primary'>
                  <Eye size={16} />
                </Button.Ripple>
              </div> */}
              <div>
                <Button.Ripple id={`edit${row.id}`} className='btn-icon' color='flat-warning' onClick={() => setIsShowModalAgent(!isShowModalAgent)}>
                  <Edit size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`edit${row.id}`}>
                  Chỉnh sửa
                </UncontrolledTooltip>
              </div>
              <div>
                <Button.Ripple id={`delete${row.id}`} className='btn-icon' color='flat-danger' onClick={() => handleDeleteAgency(row.id)}>
                  <Delete size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`delete${row.id}`}>
                  Xóa
                </UncontrolledTooltip>
              </div>
          </div>
        </Fragment>
      )
    }
  }
  // ,{
  //   sortable: true,
  //   name: 'Salary',
  //   minWidth: '150px',
  //   selector: row => row.salary
  // }
]


export default ExpandableTable
